-- Practice database for the SQL tutorials (generated by tools/build_db.py)
CREATE TABLE films (id INTEGER PRIMARY KEY, title TEXT, release_year INTEGER, country TEXT, duration INTEGER, language TEXT, certification TEXT, gross INTEGER, budget INTEGER);
CREATE TABLE people (id INTEGER PRIMARY KEY, name TEXT, birthdate TEXT, deathdate TEXT);
CREATE TABLE reviews (id INTEGER PRIMARY KEY, film_id INTEGER, num_user INTEGER, num_critic INTEGER, imdb_score REAL, num_votes INTEGER, facebook_likes INTEGER);
CREATE TABLE countries (code TEXT PRIMARY KEY, name TEXT, continent TEXT, region TEXT, capital TEXT, indep_year INTEGER, surface_area REAL);
CREATE TABLE cities (name TEXT, country_code TEXT, city_proper_pop REAL, metroarea_pop REAL);
CREATE TABLE languages (lang_id INTEGER PRIMARY KEY, code TEXT, name TEXT, percent REAL, official INTEGER);
CREATE TABLE economies (econ_id INTEGER PRIMARY KEY, code TEXT, year INTEGER, income_group TEXT, gdp_percapita REAL, gross_savings REAL, inflation_rate REAL, total_investment REAL, unemployment_rate REAL);
CREATE TABLE economies2015 (code TEXT, year INTEGER, income_group TEXT, gross_savings REAL);
CREATE TABLE economies2019 (code TEXT, year INTEGER, income_group TEXT, gross_savings REAL);
CREATE TABLE currencies (curr_id INTEGER PRIMARY KEY, code TEXT, basic_unit TEXT, curr_code TEXT);
CREATE TABLE populations (pop_id INTEGER PRIMARY KEY, country_code TEXT, year INTEGER, fertility_rate REAL, life_expectancy REAL, size REAL);
CREATE TABLE country (id INTEGER PRIMARY KEY, name TEXT);
CREATE TABLE league (id INTEGER PRIMARY KEY, country_id INTEGER, name TEXT);
CREATE TABLE team (id INTEGER PRIMARY KEY, team_api_id INTEGER, team_long_name TEXT, team_short_name TEXT, country_id INTEGER);
CREATE TABLE match (id INTEGER PRIMARY KEY, country_id INTEGER, season TEXT, stage INTEGER, date TEXT, hometeam_id INTEGER, awayteam_id INTEGER, home_goal INTEGER, away_goal INTEGER);
CREATE VIEW matches_germany AS SELECT * FROM match WHERE country_id = 3;
CREATE VIEW matches_italy AS SELECT * FROM match WHERE country_id = 4;
CREATE VIEW matches_spain AS SELECT * FROM match WHERE country_id = 7;
CREATE VIEW teams_spain AS SELECT * FROM team WHERE country_id = 7;
CREATE VIEW matches_2013_2014 AS SELECT * FROM match WHERE season = '2013/2014';
CREATE TABLE product (ProductID INTEGER PRIMARY KEY, Name TEXT, ListPrice REAL);
CREATE TABLE departments (department_id INTEGER PRIMARY KEY, department_name TEXT);
CREATE TABLE employees (employee_id INTEGER PRIMARY KEY, employee_name TEXT, department_id INTEGER, salary INTEGER);
CREATE TABLE matches (match_id INTEGER PRIMARY KEY, match_date TEXT, team TEXT, opponent TEXT, goals_scored INTEGER, goals_conceded INTEGER, season TEXT);
CREATE TABLE teams (team_id INTEGER PRIMARY KEY, team_name TEXT, city TEXT, stadium TEXT);
CREATE TABLE seasons (season_id INTEGER PRIMARY KEY, season_name TEXT, start_date TEXT, end_date TEXT);
CREATE TABLE stores (store_id INTEGER PRIMARY KEY, store_name TEXT, city TEXT);
CREATE TABLE products (product_id INTEGER PRIMARY KEY, product_name TEXT, category TEXT, price REAL, supplier_id INTEGER, product_code TEXT);
CREATE TABLE customers (customer_id INTEGER PRIMARY KEY, customer_name TEXT, email TEXT);
CREATE TABLE sales (sale_id INTEGER PRIMARY KEY, transaction_date TEXT, store_id INTEGER, product_id INTEGER, quantity INTEGER, amount REAL, customer_id INTEGER);
CREATE TABLE inventory (product_id INTEGER PRIMARY KEY, current_stock INTEGER);
CREATE TABLE products_history (product_key INTEGER PRIMARY KEY, product_id INTEGER, price REAL, valid_from TEXT, valid_to TEXT, is_current INTEGER);
